item.command:
/bin/zsh -lc "apply_patch <<'PATCH'
*** Begin Patch
*** Update File: TopModule.sv
@@
         if ("'!rst_n)
             q <= 6'"'b001011;
         else
-            q <= {q[5], q[4:0]};
+            q <= {q[4:0], q[5]};
*** End Patch
PATCH

cat > tb.sv <<'EOF'
module tb;
  reg clk = 0;
  reg rst_n = 0;
  wire data;
  TopModule dut(.clk(clk), .rst_n(rst_n), .data(data));

  always #5 clk = ~clk;

  integer i;
  reg [5:0] seen;
  initial begin
    seen = 6'b0;
    #12;
    rst_n = 1;
    for (i = 0; i < 6; i = i + 1) begin
      @(posedge clk);
      #1;
      seen[5-i] = data;
      "'$display("cycle %0d data=%0b", i, data);
    end
    if (seen !== 6'"'b001011) begin
      "'$display("FAIL saw %b expected 001011", seen);
      $finish_and_return(1);
    end
    $display("PASS saw %b", seen);
    $finish;
  end
endmodule
EOF

iverilog -g2012 -o simv TopModule.sv tb.sv && vvp simv'

